    Bug 2022038 - Use console.error instead of dump for CLI warnings in MessengerContentHandler. r=mkmelin


    Currently, when Thunderbird is launched with unrecognized command-line
    flags, the warning is passed to `dump()`. In release builds, `dump()`
    output is suppressed by default (unless the preference
    `browser.dom.window.dump.enabled` is set to true), causing these
    diagnostic warnings to be entirely lost.

    This patch replaces `dump()` calls with `console.error()` in
    `MessengerContentHandler.sys.mjs`. This ensures that command-line
    parsing warnings and related exceptions are reliably logged to
    Thunderbird's internal Error Console (Ctrl+Shift+J) without altering
    the application's startup flow.

    Differential Revision: https://phabricator.services.mozilla.com/D287547

diff --git a/mail/components/MessengerContentHandler.sys.mjs b/mail/components/MessengerContentHandler.sys.mjs
index 163458038d1..ce08098000b 100644
--- a/mail/components/MessengerContentHandler.sys.mjs
+++ b/mail/components/MessengerContentHandler.sys.mjs
@@ -368,7 +368,7 @@ export class MessengerContentHandler {
           cmdLine.preventDefault = true;
         }
       } catch (e) {
-        dump(e);
+        console.error(e);
       }
     }

@@ -471,11 +471,10 @@ export class MessengerContentHandler {
           break;
         }

-        dump("Warning: unrecognized command line flag " + curarg + "\n");
+        console.error(`Warning: unrecognized command line flag ${curarg}`);
         // To emulate the pre-nsICommandLine behavior, we ignore the
         // argument after an unrecognized flag.
         i += 2;
-        // xxxbsmedberg: make me use the console service!
       }

       if (i < count) {
@@ -508,7 +507,7 @@ export class MessengerContentHandler {
           return;
         }
